"""One hundred authored roadside situations; no random combinations or runtime import."""
from encounter_helpers import choice as C, event, write

rows = []


def add(title, context, held, action, cost, outcome, reward, alternative, alt_cost,
        alt_outcome, gap, place="wilderness", skill=None, alt_reward=()):
    n = len(rows) + 1
    dependencies = sorted(set(["item_ownership", "exploration"] + gap.split()))
    rows.append(event(f"wild_{n:03}", "wilderness", title, context, [place],
        "trade" if "regional_trade" in dependencies else "survival" if "hazards" in dependencies else "explore",
        [C(action, cost, outcome, held=held, skill=skill, rewards=reward),
         C(alternative, alt_cost, alt_outcome, rewards=alt_reward),
         C("保留補給，離開現場", "額外時間 0 天；不取得現場物品。", "不介入這次事件，原有旅程繼續；沒有新增報酬。")],
        f"後續只追蹤「{title}」已選方案的現場與物品去向；不得重新生成同一份回收物或推定受助者生死。",
        dependencies, ["LD-P01", "WG-04", "FICTION-ROAD"] if n % 2 else ["LD-P02", "WG-01", "FICTION-METRO"] ))


