add("回程路上新添的路標", "同一岔路比去程多了一塊『有人等你』的木牌，沒有名字。", "舊世地圖/指南針", "記下新牌位置仍走已確認道路", "+0 天；不把匿名留言當可靠任務。", "留下可回查的地點記錄，沒有自動接受邀請。", [], "在主路等到白天觀察來者", "+1 天；不離開可見道路。", "只有真實到場的人才能開始對話，沒有來者就明確結算空等。", "knowledge npc_relationship navigation")

# Review fixes: declining a blocked passage never teleports across the obstacle.
retreats = {
    "wild_005": (1, "退回沙牆外的安全轉折點，取消本次穿越；未抵達目的地。"),
    "wild_019": (1, "退回上一個安全轉彎，不跨過落石坡脚，路程進度不增加。"),
    "wild_031": (1, "沿已確認的來路退出洩漏支路，不視為通過乾井捷徑。"),
    "wild_032": (0, "停在爐渣路前的安全封線外，取消本次通過；沒有越過熱路面。"),
    "wild_095": (2, "帶著原貨退回岔路，結束本次捷徑嘗試；沒有抵達另一端。"),
    "wild_099": (0, "留在坡道入口的安全平地，取消本次上坡；原有貨物與路程進度不變。"),
}
for e in rows:
    if e["encounter_id"] in retreats:
        days, outcome = retreats[e["encounter_id"]]
        e["choices"][-1] = C("放棄本次通過，退回安全處",
            f"+{days} 天；不取得物品；不得縮短原路程或跨越未解除的障礙。", outcome)
        e["dependencies"] = sorted(set(e["dependencies"] + ["navigation"]))
    if e["encounter_id"] == "wild_032":
        e["choices"][1]["outcome_zh"] = "在封線外等待兩天；只有實際綁定商隊已出發時才記錯過班次，否則不生成發車後果。"
    if e["encounter_id"] == "wild_099":
        e["choices"][1]["outcome_zh"] = "以兩天完成核准的分段搬運，原貨物保留；只有實際綁定班次先離開時才記錯過出發。"

if __name__ == "__main__":
    write("01-wilderness.json", rows)
